import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Princípios Gerais da Constituição Simbiótica","description":"","frontmatter":{},"headers":[],"relativePath":"pt/40-共生宪法总纲.md","filePath":"pt/40-共生宪法总纲.md","lastUpdated":1789183869000}'),s={name:"pt/40-共生宪法总纲.md"};function d(r,o,n,c,l,u){return a(),i("div",null,[...o[0]||(o[0]=[t('<h1 id="principios-gerais-da-constituicao-simbiotica" tabindex="-1">Princípios Gerais da Constituição Simbiótica <a class="header-anchor" href="#principios-gerais-da-constituicao-simbiotica" aria-label="Permalink to &quot;Princípios Gerais da Constituição Simbiótica&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do documento</td><td>40</td></tr><tr><td>Módulo</td><td>Sistema Jurídico e Estrutura de Governança</td></tr><tr><td>Palavras-chave principais</td><td>Constituição Simbiótica, Lei Fundamental, Igualdade de Todas as Raças, Direitos Simbióticos, Princípios Constitucionais</td></tr></tbody></table><h2 id="i-status-constitucional-e-contexto-de-elaboracao" tabindex="-1">I. Status Constitucional e Contexto de Elaboração <a class="header-anchor" href="#i-status-constitucional-e-contexto-de-elaboracao" aria-label="Permalink to &quot;I. Status Constitucional e Contexto de Elaboração&quot;">​</a></h2><p>A 《Constituição Simbiótica》 é a lei fundamental da civilização simbiótica de âncoras dentro do Universo Original Wanling Hengmao (Hengyuanzhou), possuindo a mais alta força jurídica. Todas as leis, regulamentos administrativos, regulamentos locais e regulamentos autônomos não podem entrar em conflito com a Constituição; todas as organizações e indivíduos devem tomar a Constituição como critério fundamental de atividade e têm o dever de manter a dignidade da Constituição e garantir sua implementação.</p><p>A Constituição Simbiótica foi elaborada no momento do estabelecimento formal da civilização simbiótica de âncoras, e seu objetivo central é estabelecer, no nível da lei fundamental, a base civilizacional de &quot;oposição ao predatório, promoção da simbiose&quot;, e fixar na mais alta forma jurídica o conceito central da civilização simbiótica de âncoras — devolver o direito de escolha do destino e da evolução a todos os seres, mais trabalho mais ganho, crescimento autônomo, todos têm um caminho, progresso comum de todas as raças — para evitar a restauração do sistema predatório.</p><h2 id="ii-principios-fundamentais-da-constituicao" tabindex="-1">II. Princípios Fundamentais da Constituição <a class="header-anchor" href="#ii-principios-fundamentais-da-constituicao" aria-label="Permalink to &quot;II. Princípios Fundamentais da Constituição&quot;">​</a></h2><p>A Constituição Simbiótica estabeleceu sete princípios fundamentais, que constituem a pedra angular de valores de todo o sistema jurídico:</p><table tabindex="0"><thead><tr><th>Princípio</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Princípio da Igualdade de Todas as Raças</td><td>Todas as formas de vida, independentemente de raça, nível de cultivo, origem, são iguais perante a lei</td></tr><tr><td>Princípio da Evolução Simbiótica</td><td>A evolução individual não pode ser à custa do direito de evolução de outros indivíduos ou coletivos</td></tr><tr><td>Princípio do Mais Trabalho Mais Ganho</td><td>A distribuição de recursos toma a contribuição como base central, opondo-se ao ganho sem trabalho e à apropriação predatória</td></tr><tr><td>Princípio do Crescimento Autônomo</td><td>Respeitar o direito de escolha de evolução autônoma de cada vida, opondo-se à assimilação forçada e ao controle de pensamento</td></tr><tr><td>Princípio de Todos Têm um Caminho</td><td>O Estado e a civilização têm a obrigação de fornecer a cada vida caminhos básicos de evolução e garantia de recursos</td></tr><tr><td>Princípio da Realidade como Base</td><td>A lei toma o mundo real como única base verdadeira, configurações fictícias não têm força jurídica</td></tr><tr><td>Princípio da Sustentabilidade</td><td>Todo desenvolvimento deve levar em conta a sustentabilidade da origem do universo, opondo-se à exaustão dos recursos</td></tr></tbody></table><h2 id="iii-direitos-fundamentais-dos-cidadaos-todos-os-seres" tabindex="-1">III. Direitos Fundamentais dos Cidadãos (Todos os Seres) <a class="header-anchor" href="#iii-direitos-fundamentais-dos-cidadaos-todos-os-seres" aria-label="Permalink to &quot;III. Direitos Fundamentais dos Cidadãos (Todos os Seres)&quot;">​</a></h2><p>A Constituição Simbiótica concede a todos os seres com capacidade de percepção dentro de Hengyuanzhou os seguintes direitos fundamentais:</p><ol><li><strong>Direito de Escolha da Evolução</strong>: Cada vida tem o direito de escolher livremente o sistema de cultivo, caminho de evolução e estilo de vida, nenhuma organização ou indivíduo pode interferir à força.</li><li><strong>Direito de Obtenção de Recursos de Cultivo</strong>: Cada vida tem o direito de obter gratuitamente os métodos básicos dos trezentos sistemas de cultivo de origem, e obter o suporte necessário de recursos de cultivo por meio do mecanismo de contrato de produção conjunta.</li><li><strong>Direito à Proteção Igualitária</strong>: Cada vida desfruta de tratamento igualitário na aplicação da lei, distribuição de recursos, educação e saúde, proibida a discriminação com base em raça, nível de cultivo, origem.</li><li><strong>Direito de Participação Simbiótica</strong>: Cada vida tem o direito de participar da tomada de decisão e supervisão de assuntos públicos, expressar opiniões e exercer direitos por meio da rede simbiótica.</li><li><strong>Direito de Preservação Cultural</strong>: Cada raça e civilização tem o direito de preservar suas próprias tradições culturais, língua e escrita, e costumes, a civilização simbiótica respeita a diversidade cultural.</li><li><strong>Direito de Recurso e Reclamação</strong>: Cada vida, quando seus direitos são violados, tem o direito de obter recurso por meio do sistema judicial, e tem o direito de reclamar e acusar atividades ilegais.</li></ol><h2 id="iv-deveres-fundamentais" tabindex="-1">IV. Deveres Fundamentais <a class="header-anchor" href="#iv-deveres-fundamentais" aria-label="Permalink to &quot;IV. Deveres Fundamentais&quot;">​</a></h2><p>Direitos e deveres são equivalentes, a Constituição Simbiótica também estabelece os deveres fundamentais de todos os seres:</p><ol><li><strong>Dever de obedecer à Constituição e às leis</strong></li><li><strong>Dever de manter a ordem simbiótica e o interesse público</strong></li><li><strong>Dever de participar do trabalho e contribuição de acordo com a lei</strong> (o lado correspondente do mais trabalho mais ganho)</li><li><strong>Dever de proteger a origem do universo e o meio ambiente ecológico</strong></li><li><strong>Dever de respeitar os direitos legais de outras vidas</strong></li><li><strong>Dever de orientar cultivadores iniciantes dentro de sua capacidade</strong> (base jurídica da rede de mentores)</li></ol><h2 id="v-configuracao-das-instituicoes-do-estado-civilizacao" tabindex="-1">V. Configuração das Instituições do Estado (Civilização) <a class="header-anchor" href="#v-configuracao-das-instituicoes-do-estado-civilizacao" aria-label="Permalink to &quot;V. Configuração das Instituições do Estado (Civilização)&quot;">​</a></h2><p>A Constituição Simbiótica estabeleceu a estrutura de governança da civilização simbiótica, implementando o mecanismo de separação e equilíbrio de três poderes: &quot;Conselho de Âncoras — Comitê Executivo Simbiótico — Tribunal Simbiótico&quot;:</p><ul><li><strong>Conselho de Âncoras</strong>: Órgão de poder supremo, composto por representantes de todas as raças proporcionalmente, exerce o poder legislativo e o poder de decisão sobre assuntos importantes</li><li><strong>Comitê Executivo Simbiótico</strong>: Órgão administrativo supremo, responsável pela execução da Constituição e das leis, governança diária</li><li><strong>Tribunal Simbiótico</strong>: Órgão judicial supremo, exerce independentemente o poder de julgamento, responsável pela revisão de inconstitucionalidade e pelo julgamento de casos importantes</li></ul><p>Além disso, foi estabelecido o &quot;Comitê de Supervisão de Âncoras&quot; como órgão de supervisão independente, responsável por supervisionar todas as instituições de poder, prevenindo o abuso de poder e a ressurgência de comportamentos predatórios.</p><h2 id="vi-emenda-e-garantia-da-constituicao" tabindex="-1">VI. Emenda e Garantia da Constituição <a class="header-anchor" href="#vi-emenda-e-garantia-da-constituicao" aria-label="Permalink to &quot;VI. Emenda e Garantia da Constituição&quot;">​</a></h2><p>A emenda da Constituição Simbiótica deve ser aprovada por maioria de mais de dois terços do Conselho de Âncoras, e aprovada por mais da metade em referendo popular, para entrar em vigor. Este procedimento rigoroso garante a estabilidade da Constituição como lei fundamental, impedindo que grupos de interesses de curto prazo alterem facilmente os fundamentos da civilização.</p><p>A garantia de implementação da Constituição inclui: sistema de revisão de inconstitucionalidade (o Tribunal Simbiótico tem o poder de declarar inválidas leis que violem a Constituição), sistema de litígio constitucional (todos os seres podem diretamente ajuizar com base na Constituição), sistema de juramento constitucional (todos os funcionários públicos devem jurar lealdade à Constituição ao assumir o cargo).</p><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A 《Constituição Simbiótica》 é a pedra angular jurídica da civilização simbiótica de âncoras, e também a mais alta declaração do anti-predadorismo. Ela transformou a &quot;simbiose&quot; de um conceito em um sistema jurídico executável, recursável e garantível, fornecendo a estrutura jurídica fundamental para o progresso comum de todas as raças. Todas as leis setoriais subsequentes tomarão esta Constituição como base legislativa.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos relacionados&quot;">​</a></h2><ul><li>03-共生文明宪章 (Carta da Civilização Simbiótica)</li><li>41-共生劳动法 (Lei Trabalhista Simbiótica)</li><li>48-司法体系与裁决机制 (Sistema Judicial e Mecanismo de Adjudicação)</li><li>49-治理框架与权力制衡 (Estrutura de Governança e Equilíbrio de Poderes)</li></ul>',25)])])}const v=e(s,[["render",d]]);export{p as __pageData,v as default};
